#include "exotic/autonomy/agents/sqlite_repository.hpp"
#include <cassert>
#include <filesystem>
using namespace exotic::autonomy;using namespace exotic::autonomy::agents;
int main(){auto path=std::filesystem::temp_directory_path()/"exotic-agent-v06-test.db";std::filesystem::remove(path);{SqliteAgentRepository repo{path};AgentIdentity a;a.id=1;a.identity_key="sqlite-agent";a.display_name="SQLite Agent";a.status=AgentStatus::Active;a.health=HealthState::Healthy;a.trust=TrustLevel::Elevated;a.roles={"operator"};a.attributes={{"environment","test"}};a.domain_scopes={"software"};a.specialist.tags={"cpp","sqlite"};a.runtime.attributes={{"host","local"}};a.last_heartbeat_at=Clock::now();repo.save_agent(a);CapabilityDefinition d;d.id=1;d.key="software.cpp";d.name="C++";d.required_tools={"compiler"};repo.save_capability_definition(d);repo.save_agent_capability({1,"software.cpp",0.9,0.8,2,1,Clock::now()});ToolPermission p;p.agent_id=1;p.tool_key="compiler";p.operations={"build"};repo.save_tool_permission(p);WorkAssignment wa;wa.id=1;wa.job_id=8;wa.proposal_id=9;wa.requirement.job_id=8;wa.requirement.proposal_id=9;wa.requirement.capabilities={{"software.cpp",0.8,0.7,true,1.0}};wa.requirement.resource_account_id=4;wa.plan.agent_ids={1};wa.plan.stages={{0,"build",WorkPlanMode::Single,{1},{}}};wa.continuity_key="job:8";repo.save_assignment(wa);}{SqliteAgentRepository repo{path};auto a=repo.load_agent(1);assert(a&&a->roles.size()==1&&a->specialist.tags.size()==2);assert(repo.load_agent_capabilities(1).size()==1);assert(repo.load_tool_permissions(1).front().operations.contains("build"));auto wa=repo.find_assignment_by_job(8);assert(wa&&wa->requirement.capabilities.size()==1&&wa->plan.agent_ids.front()==1&&wa->plan.stages.size()==1);}std::filesystem::remove(path);return 0;}
